/** A person the search found, always as their master record (merged profiles are never hits of their own). */
export interface PatientSearchHitOut {
  patient_id: number;
  /** The newest Patient Photo of the merge chain, for the identity check; null when none was taken (it is optional). GET /patient-documents/{document_id}/download */
  photo_document_id: number | null;
  mrn: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  full_name: string;
  father_or_husband_name: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  dob: string | null;
  age_years: number | null;
  /** When age_years was recorded (the age grows from that date) */
  age_recorded_on: string | null;
  mobile: string | null;
  cnic: string | null;
  /** The Universal Patient Medical Record Number when one was recorded (optional) */
  upmrn: string | null;
  address: string | null;
  emergency_contact_name: string | null;
  emergency_contact_phone: string | null;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  allergies: string | null;
  billing_category: "Cash" | "Panel";
  panel_id: number | null;
  panel_name: string | null;
  panel_member_no: string | null;
  /** Unknown-trauma label, e.g. "Unknown Male 3" */
  temp_identifier: string | null;
  merged_into_id: number | null;
  linked_employee_id: number | null;
  is_deceased: boolean;
  /** The death record (GET /deaths/{death_id}) when the death is recorded */
  death_id: number | null;
  death_at: string | null;
  /** Medico-legal case numbers of this person: show a MEDICO-LEGAL banner when not empty (MSDS 154: the record is clearly so marked) */
  mlc_numbers: string[];
  created_at: string;
  row_version: number;
  outstanding: OutstandingBannerOut;
  /** The profile merged into this record that the search matched when this record itself did not (an old slip's MRN, a trauma label such as "Unknown Male 3", a duplicate's name or numbers): say "Found by MRN-…, merged into this record". Null when this record matched */
  matched_merged_profile: MergedProfileOut | null;
}

/** Outstanding dues of the patient's whole merge chain (workflow sections 1.2 and 1.9). */
export interface OutstandingBannerOut {
  has_outstanding_ar: boolean;
  outstanding_ar_balance: number;
  /** True: reception blocks a new OPD slip unless ER bypass or an override */
  ar_block_applies: boolean;
  /** Show it prominently, e.g. "OUTSTANDING BALANCE: RS. 2,500" */
  banner_text: string | null;
}

/** Another record of the same person, merged into this one (e.g. a trauma registration). */
export interface MergedProfileOut {
  patient_id: number;
  mrn: string;
  full_name: string;
  registration_type: "Regular" | "LabOnly" | "TraumaTemp" | "Merged";
  temp_identifier: string | null;
}

/** Find blood donors — GET /api/v1/blood-center/donors (who may call: holders of blood_center.view). */
export function listDonors(query: { q: string; limit?: number; before_id?: number | null }): Promise<DonorOut[]> {
  return api<DonorOut[]>("GET", withQuery(`/blood-center/donors`, query), undefined);
}

/** One donor's record — GET /api/v1/blood-center/donors/{donor_id} (who may call: holders of blood_center.view). */
export function getDonor(donor_id: number): Promise<DonorDetailOut> {
  return api<DonorDetailOut>("GET", `/blood-center/donors/${donor_id}`, undefined);
}

/** Assess a donor: accept or defer — POST /api/v1/blood-center/donations (who may call: holders of blood_center.donor.assess). */
export function assessBloodCenterDonations(body: DonationIn): Promise<DonationOut> {
  return api<DonationOut>("POST", `/blood-center/donations`, body, { idempotent: true });
}

/** Donations and the worklists — GET /api/v1/blood-center/donations (who may call: holders of blood_center.view). */
export function listDonations(query?: { status?: "Accepted" | "Deferred" | "Collected" | "Unsuccessful" | "Cleared" | "Reactive" | "Rejected" | null; donor_id?: number | null; date_from?: string | null; date_to?: string | null; limit?: number; before_id?: number | null }): Promise<DonationOut[]> {
  return api<DonationOut[]>("GET", withQuery(`/blood-center/donations`, query), undefined);
}

/** One donation, from the donor to the patients — GET /api/v1/blood-center/donations/{donation_id} (who may call: holders of blood_center.view). */
export function getDonation(donation_id: number): Promise<DonationDetailOut> {
  return api<DonationDetailOut>("GET", `/blood-center/donations/${donation_id}`, undefined);
}

/** Defer a donor — POST /api/v1/blood-center/donors/{donor_id}/deferrals (who may call: holders of blood_center.donor.assess). */
export function addDeferral(donor_id: number, body: DonorDeferralIn): Promise<DonorDeferralOut> {
  return api<DonorDeferralOut>("POST", `/blood-center/donors/${donor_id}/deferrals`, body, { idempotent: true });
}

/** Record how the donor was told — POST /api/v1/blood-center/deferrals/{deferral_id}/inform (who may call: holders of blood_center.donor.assess). */
export function inform(deferral_id: number, body: DonorTellIn): Promise<DonorDeferralOut> {
  return api<DonorDeferralOut>("POST", `/blood-center/deferrals/${deferral_id}/inform`, body);
}

/** Revoke a deferral entered in error — POST /api/v1/blood-center/deferrals/{deferral_id}/revoke (who may call: holders of blood_center.donor.assess). */
export function revokeBloodCenterDeferrals(deferral_id: number, body: DeferralRevokeIn): Promise<DonorDeferralOut> {
  return api<DonorDeferralOut>("POST", `/blood-center/deferrals/${deferral_id}/revoke`, body);
}

/** Returning-patient lookup by name / phone / CNIC / UPMRN / MRN — GET /api/v1/patients/search (who may call: holders of patient.search). */
export function searchPatients(query: { q: string; limit?: number }): Promise<PatientSearchHitOut[]> {
  return api<PatientSearchHitOut[]>("GET", withQuery(`/patients/search`, query), undefined);
}
